We start by proving the following 2 auxiliary statements:

\begin{restatable}[Masking for $\Int$]{lemma}{lemmaskingint} \label{lem:masking-int}
Let $X, Y, U \subseteq \set{0,\dots,n}$. There are sets \makebox{$X', U' \subseteq \set{0,\dots, 2^{17} n^2}$} that can be constructed in time~$\poly(n)$ and satisfying that:
\begin{equation*}
    \exists A \subseteq U : X \subseteq A + A \subseteq Y \qquad\text{if and only if}\qquad \exists A' \subseteq U' : X' = A' + A'.
\end{equation*}
\end{restatable}
\begin{proof}[Proof of \cref{lem:masking-int}]
By first applying the transformation from \cref{lem:range-int}, we assume throughout that $X, Y, U \subseteq [0,32n]$ with $\min(X) = \min(Y) = \min(U) = 0$, $\max(X) = \max(Y) = 32n$ and $\max(U) = 16n$, and that all three sets contain only even numbers. For simplicity, we write~\makebox{$N = 16n$}. Furthermore, if $X \not\subseteq Y$, then the reduction is trivial, so assume that $X \subseteq Y$ and let $Z = Y \setminus X$. In this proof, we will construct sets~\makebox{$X', U' \subseteq \Int$} containing negative integers; this can later be fixed by shifting all sets appropriately into the positive range.

The construction of the sets $X'$ and $U'$ is, unfortunately, extremely tedious. We define
\begin{align*}
    X' = \bigcup_{\substack{-2 \leq c \leq 2\\-8N \leq k \leq 8N}} (c \cdot 64N^2 + k \cdot 4N + X'_{c, k}), \\
    U' = \bigcup_{\substack{-1 \leq a \leq 1\\-4N \leq i \leq 4N}} (a \cdot 64N^2 + i \cdot 4N + U'_{a, i}),
\end{align*}
where the pieces $X'_{c, k} \subseteq [0,2N]$ and $U'_{a, i} \subseteq [0,N]$ are defined as follows; we write $I = [-4N,4N] \setminus \set{0}$ for simplicity here:
\begin{alignat*}{3}
    &X'_{2, k} &&= [0,2N] &&\qquad(\text{for $k \in I + I$}), \\
    &X'_{1, k} &&= [0,2N] &&\qquad(\text{for $k \in I$}), \\
    &X'_{1, k} &&= \bigcup_{\substack{i \in I, z \in Z\\i \pm z = k}} [z/2, z/2 + N] &&\qquad(\text{for $k \not\in I$}), \\
    &X'_{0, 0} &&= Y, \\
    &X'_{0, k} &&= [0,2N] &&\qquad(\text{for $k \in I$}), \\
    &X'_{-1, 0} &&= [0,2N], \\
    &X'_{-1, z} &&= X'_{-1, -z} = [z/2, z/2 + N] &&\qquad(\text{for $z \in Z$}), \\
    &X'_{-2, 0} &&= [0,2N],
\end{alignat*}
and
\begin{alignat*}{3}
    &U'_{1, i} &&= [0,N] &&\qquad(\text{for $i \in I$}), \\
    &U'_{0, 0} &&= U, \\
    &U'_{0, z} &&= U'_{0, -z} = \set{z/2} &&\qquad(\text{for $z \in Z$}), \\
    &U'_{-1, 0} &&= [0,N].
\end{alignat*}
Moreover, all sets $X'_{\ell, i}$ and $U'_{\ell, i}$ which are not covered by these cases are defined to be empty.

Before checking the soundness and completeness properties, we first check that the size of~$X', U'$ is appropriate. We have that $X', U' \subseteq [-256N^2, 256N^2]$, and thus by shifting them into the positive range, we would obtain sets in $[0, 512N^2]$. Recalling that $N = 16n$, the universe bound $512 N^2 = 2^{17} n$ holds.

\paragraph{Soundness}
Suppose that there is some set $A \subseteq U$ with $X \subseteq A + A \subseteq Y$. We give a set $A' \subseteq U'$ with $X' = A' + A'$. As before, we define
\begin{equation*}
    A' = \bigcup_{\substack{-1 \leq a \leq 1\\-4N \leq i \leq 4N}} (a \cdot 64N^2 + i \cdot 4N + A'_{a, i})
\end{equation*}
where $A'_{a, i} \subseteq [0,n]$ is defined as follows:
\begin{alignat*}{3}
    &A'_{1, i} &&= [0,N] &&\qquad(\text{for $i \in I$}), \\
    &A'_{0, 0} &&= A, \\
    &A'_{0, z} &&= A'_{0, -z} = \set{z/2} &&\qquad(\text{for $z \in Z$}), \\
    &A'_{-1, 0} &&= [0,N].
\end{alignat*}
From the construction, it is immediate that $A' \subseteq U'$. Observe further that $0, N \in A$ (as otherwise we cannot satisfy that $\set{0, 2N} \subseteq X \subseteq A + A$), and thus 
$A + [0,N] = [0,2N]$; this observation will be useful in the following paragraphs.

Next, we show that $A' + A' \subseteq X'$. To this end, we verify that $A'_{a, i} + A'_{b, j} \subseteq X'_{a+b,i+j}$ for all choices~$a, b, i, j$. This is not hard, but it requires a lot of case work. We state the relevant cases and omit some others due to symmetries:
\begin{alignat*}{3}
    &A'_{1, i} + A'_{1, j} &&= [0,2N] = X'_{2, i+j} &&\qquad\text{(for $i, j \in I$)}, \\
    &A'_{1, i} + A'_{0, 0} &&= [0,N] + A = [0,2N] = X'_{1, i} &&\qquad\text{(for $i \in I$)}, \\
    &A'_{1, i} + A'_{0, z} &&= [0,N] + \set{z/2} = [z/2,  z/2 + N] \subseteq X'_{1, i + z} &&\qquad\text{(for $i \in I, z \in Z$)}, \\
    &A'_{1, i} + A'_{-1, 0} &&= [0,2N] = X'_{0, i} &&\qquad\text{(for $i \in I, z \in Z$)}, \\
    &A'_{0, 0} + A'_{0, 0} &&= A + A \subseteq Y = X'_{0, 0}, \\
    &A'_{0, 0} + A'_{0, z} &&= A + \set{z/2} \subseteq [0,2N] = X'_{0, z} &&\qquad\text{(for $z \in Z$)}, \\
    &A'_{0, 0} + A'_{-1, 0} &&= A + [0,N] = [0,2N] = X'_{-1, 0}, \\
    &A'_{0, z} + A'_{0, z'} &&= \set{z/2} + \set{z/2} \subseteq [0,2N] = X'_{0, z+z'} &&\qquad\text{(for $z, z' \in Z$)}, \\
    &A'_{0, z} + A'_{0, -z} &&= \set{z/2} + \set{z/2} = \set{z} \subseteq Z \subseteq Y = X'_{0, 0} &&\qquad\text{(for $z \in Z$)}, \\
    &A'_{0, z} + A'_{-1, 0} &&= \set{z/2} + [0,N] = [z/2, z/2 + N] = X'_{-1, z} &&\qquad\text{(for $z \in Z$)}, \\
    &A'_{-1, 0} + A'_{-1, 0} &&= [0, 2N] = X'_{-2, 0}.
\end{alignat*}

Let us finally check that $X' \subseteq A' + A'$. That is, our task is to verify that for all pairs $c, k$ it holds that
\begin{equation*}
    X'_{c, k} \subseteq \bigcup_{\substack{a + b = c\\i + j = k}} (A'_{a, i} + A'_{b, j}).
\end{equation*}
This again involves dealing with many cases:
\begin{alignat*}{3}
    &X'_{2, k} &&= [0,2N] = A'_{1, i} + A'_{1, j} &&\qquad\text{(for $k = i + j \in I + I$)}, \\
    &X'_{1, k} &&= [0,2N] = A + [0,N] = A'_{0, 0} + A'_{1, k} &&\qquad\text{(for $k \in I$)}, \\
    &X'_{1, k} &&= \bigcup_{\substack{i \in I, z \in Z\\i \pm z = k}} [z/2, z/2 + N] = \bigcup_{\substack{i \in I, z \in Z\\i \pm z = k}} (A'_{1, i} + A'_{0, z}) &&\qquad\text{(for $k \not\in I$)}, \\
    &X'_{0, 0} &&= Y = X \cup Z \\
    & &&\subseteq (A + A) \cup \bigcup_{z \in Z} (\set{z/2} + \set{z/2}) \\
    & &&= (A'_{0, 0} + A'_{0, 0}) \cup \bigcup_{z \in Z} (A'_{0, z} \cup A'_{0, -z}), \\
    &X'_{0, k} &&= [0,2N] = A'_{1, k} + A'_{-1, 0} &&\qquad\text{(for $k \in I$)}, \\
    &X'_{-1, 0} &&= [0, 2N] = A + [0,N] = A'_{0, 0} + A'_{-1, 0}, \\
    &X'_{-1, z} &&= [z/2, z/2 + N] = [0,N] + \set{z/2} = A'_{-1, 0} + A'_{0, z} &&\qquad\text{(for $z \in Z$)}, \\
    &X'_{-2, 0} &&= [0, 2N] = A'_{-1, 0} + A'_{-1, 0}.
\end{alignat*}

\paragraph{Completeness}
The completeness proof is simpler in comparison. Suppose that there is a set~\makebox{$A' \subseteq U'$} with $X' = A' + A'$; we show that there is some set $A \subseteq U$ satisfying that $X \subseteq A + A \subseteq Y$. Let, in analogy to before, $A'_{a, i} \subseteq [0,N]$ denote the subset of $A'$ that falls into the length-$N$ range starting at~\smash{$a \cdot 64N^2 + i \cdot 4N$}. These are the only nonempty regions in $A'$ (by the condition that~\makebox{$A' \subseteq U'$}), and therefore it holds that
\begin{equation*}
    X'_{c, k} = \bigcup_{\substack{a + b = c\\i + j = k}} (A'_{a, i} + A'_{b, j}).
\end{equation*}
On the one hand, it is clear that $A'_{0, 0} + A'_{0, 0} \subseteq X'_{0, 0} = Y$. On the other hand, by the construction, it is easy to verify that each element $x \in Y \setminus Z$ can only appear in 
\begin{equation*}
    \bigcup_{\substack{a + b = 0\\i + j = 0}} (A'_{a, i} + A'_{b, j}) = (A'_{0, 0} + A'_{0, 0}) \cup \bigcup_{z \in Z} (A'_{0, z} + A'_{0, -z})
\end{equation*}
if $x \in A'_{0, 0} + A'_{0, 0}$. In particular, this implies that $X = Y \setminus Z \subseteq A'_{0, 0} + A'_{0, 0}$. Finally, observe that trivially $A'_{0, 0} \subseteq U'_{0, 0} = U$, and therefore $A'_{0, 0}$ satisfies all three relevant conditions.

\paragraph{Running Time}
The running time due to \cref{lem:range-int} is negligible, and we can easily compute the sets $X', U'$ in polynomial time.
\end{proof}

\begin{restatable}[Positioning for $\Int$]{lemma}{lemposint} \label{lem:pos-int}
Let $X, U \subseteq \set{0,\dots,n}$. There is a set~\makebox{$X' \subseteq \set{0, \dots,2^{24} n}$} that can be constructed in time $\poly(n)$ and satisfying that:
\begin{equation*}
    \exists A \subseteq U : X = A + A \qquad\text{if and only if}\qquad \exists A' \subseteq \Int : X' = A' + A'.
\end{equation*}
\end{restatable}
\begin{proof}[Proof of \cref{lem:pos-int}]
For convenience, let us modify the input so that $\min(U) = \min(X) = 0$ and that $\max(U) = n$ and $\max(X) = 2n$ (by removing all elements larger than $\max(X) / 2$ from $U$ and shifting the sets if necessary; this transformation only decreases $n$). Let~\makebox{$a, u, s, I, I', I''$} be as in the previous lemma and write $m = 2^{21}$. We choose~\makebox{$X' = \set{i \cdot 4n + x : i \in I + I, x \in X'_i}$}, where the sets $X'_i \subseteq [0,  2n]$ are defined as follows:
\begin{alignat*}{3}
    &X'_s &&= U + \set{0, n}, \\
    &X'_{2a} &&= X, \\
    &X'_{2s - 2a} &&= X'_{2s - 2u} = \set{0, n, 2n}, \\
    &X'_{i} &&= [0,2n] &&\qquad(\text{for $i \in I + I''$}).
\end{alignat*}
\cref{lem:skeleton-int}~(iii) guarantees that these four cases indeed cover for all $i \in I + I$. This completes the description of $X'$; as claimed we have that $\max(X') \leq (4m + 2) n < 2^{24} n$.

\paragraph{Soundness}
Assume that there is a set $A \subseteq U$ with $X = A + A$; our goal is to show that there is some set $A' \subseteq \Int$ such that $X' = A' + A'$. To this end, we pick $A' = \set{i \cdot 4n + x : i \in I, x \in A'_i}$, where the sets $A'_i \subseteq [0,n]$ are defined as follows:
\begin{alignat*}{3}
    &A'_a &&= A, \\
    &A'_u &&= U, \\
    &A'_{s-a} &&= A'_{s-u} = \set{0, n}, \\
    &A'_i &&= [0,n] &&\qquad(\text{for $i \in I''$}).
\end{alignat*}

As the first step, we verify that $A' + A' \subseteq X'$. To this end, it suffices to check that~\makebox{$A'_i + A'_j \subseteq X'_{i+j}$} for all pairs~\makebox{$i, j \in I$}. This is obvious whenever $i + j \in I + I''$ since then~\smash{$X_{i+j}' = [0,2n]$}. By \cref{lem:skeleton-int}~(iii) the only other relevant cases are when $i + j \in \set{2a, 2s - 2a, 2s - 2u, s}$. By \cref{lem:skeleton-int}~(ii) the following cases are exhaustive: 
\begin{alignat*}{2}
    &A'_a + A'_a &&= A + A = X = X'_{2a}, \\
    &A'_{s - a} + A'_{s - a} &&= \set{0, n} + \set{0, n} = \set{0, n, 2n} = X'_{2s - 2a}, \\
    &A'_{s - u} + A'_{s - u} &&= \set{0, n} + \set{0, n} = \set{0, n, 2n} = X'_{2s - 2u}, \\
    &A'_a + A'_{s - a} &&= A + \set{0, n} \subseteq U + \set{0, n} = X'_s, \\
    &A'_u + A'_{s - u} &&= U + \set{0, n} = X'_s.
\end{alignat*}

Next, we verify that $X' \subseteq A' + A'$. To this end, we verify that for each $k \in I + I$ there exists some pair $i, j \in I$ such that $X'_k \subseteq A'_i + A'_j$. First, consider $k \in I + I''$. Observe that $\set{0, n} \subseteq A'_i$ for all $i \in I$. Recall that further $A'_j = \set{0, \dots, n}$ for all $j \in I''$, and hence,
\begin{equation*}
    X'_k \subseteq [0,2n] = \set{0, n} + [0,n].
\end{equation*}
By \cref{lem:skeleton-int}, these are the only remaining cases:
\begin{alignat*}{2}
    &X'_{2a} &&= X = A + A = A'_a + A'_a, \\
    &X'_{2s - 2a} &&= \set{0, n, 2n} = \set{0, n} + \set{0, n} = A'_{s - a} + A'_{s - a}, \\
    &X'_{2s - 2u} &&= \set{0, n, 2n} = \set{0, n} + \set{0, n} = A'_{s - u} + A'_{s - u}, \\
    &X'_s &&= U + \set{0, n} = A'_u + A'_{s-u}.
\end{alignat*}

\paragraph{Completeness}
Assume that there is a set $A' \subseteq \Int$ satisfying that $X' = A' + A'$. We construct a set $A \subseteq U$ with $X = A + A$. The first insight is that since $X' \subseteq \bigcup_{k \in I + I} [k \cdot 4n, k \cdot 4n + 2n]$, we have
\begin{equation*}
    A' \subseteq \bigcup_{0 \leq i \leq m} [i \cdot 2n, i \cdot 2n + n].
\end{equation*}
Importantly, $A'$ cannot contain elements from $[i \cdot 2n, i \cdot 2n + n]$ and $[j \cdot 2n, j \cdot 2n + n]$ at the same time when $i$ and $j$ have different parity. Since the smallest relevant $i$ is even (as otherwise we cannot cover $[k \cdot 4n,  k \cdot 4n + 2n]$ where $k = \min(I + I)$ is even), all relevant indices $i$ must be even. By rescaling all indices by $2$, we can thus express
\begin{equation*}
    A' = \bigcup_{0 \leq i \leq m} (4n \cdot i + A'_i),
\end{equation*}
for some sets $A'_i \subseteq [0,n]$. Moreover, we can rewrite the condition $X' = A' + A'$ as
\begin{equation*}
    X'_k = \bigcup_{\substack{0 \leq i, j \leq m\\i + j = k}} (A'_i + A'_j).
\end{equation*}
Thus, letting $J = \set{i : A'_i \neq \emptyset}$ we must have that $I + I = J + J$. Since the set $I$ is primitive by \cref{lem:skeleton-int}~(i), we conclude that $I = J$. Next, recall that $r_{I + I}(2a) = 1$ by \cref{lem:skeleton-int}~(ii), and thus
\begin{equation*}
    X = X'_{2a} = A'_a + A'_a.
\end{equation*}
\cref{lem:skeleton-int}~(ii) further guarantees that $2s - 2a$ has a unique representation, and so
\begin{alignat*}{2}
    \set{0, n, 2n} &= X'_{2s - 2a} &&= A'_{s - a} + A'_{s - a},
\end{alignat*}
entailing that $A'_{s - a} = \set{0, n}$. We finally use that
\begin{alignat*}{2}
    A'_a + \set{0, n} &= A'_a + A'_{s - a} &&\subseteq X'_s = U + \set{0, n},
\end{alignat*}
which implies that $A'_a \subseteq U$. In summary, the set $A := A'_a$ satisfies both conditions that $X = A + A$ and that $A \subseteq U$.

\paragraph{Running Time}
Let us finally comment on the running time. The set $I$ as provided by \cref{lem:skeleton-int} has constant size, and its construction time can thus be neglected. Given this, the set $X$ can easily be constructed in polynomial time by appropriately shifting and copying $X$ and $U$.
\end{proof}

With the above in mind, we are now ready to prove the main statement:

\begin{proof}[Proof of Theorem \ref{thm:np-hard-integer}]
        Let us now show a polynomial-time reduction from 3-SAT to the Sumset Recognition problem. Since the problem is clearly in NP, this will prove that the problem is NP-complete. 
        Given a 3-SAT instance; a formula $\phi$ on $n$ variables and $m$ clauses, apply the algorithm from \cref{lem:3sat-int} to obtain three sets $X,Y,U \subseteq [0,160(n+m)^2] \subseteq [0,2^8(n+m)^2]$, such that: 
        \begin{equation*}
            \text{$\phi$ is satisfiable} \qquad\text{if and only if}\qquad \exists A \subseteq U : X \subseteq A + A \subseteq Y.
        \end{equation*}
        Then, apply the algorithm from \cref{lem:masking-int} on $X,Y,U$ to obtain two sets $U',X' \subseteq [0,2^{17}\cdot (2^8(n+m)^2)^2] = [0,2^{33}(n+m)^4]$, such that: 
        \begin{equation*}
            \exists A \subseteq U : X \subseteq A + A \subseteq Y \qquad\text{if and only if}\qquad \exists A' \subseteq U' : X' = A' + A'.
        \end{equation*}
        As a corollary, $\phi$ is satisfiable if and only if $\exists A' \subseteq U'$ such that $X' = A'+A'$.
        Finally, apply the algorithm from \cref{lem:pos-int} on $X',U'$ to obtain a Sumset Recognition instance $X_{\phi} \subseteq [0,2^{24} \cdot 2^{33} (n+m)^4] = [0,2^{57}(n+m)^4]$, such that: 
        \begin{equation*}
            \exists A' \subseteq U' : X' = A' + A' \qquad\text{if and only if}\qquad \exists A'' \subseteq \Int : X_{\phi} = A'' + A''.
        \end{equation*}
        Thus, $\phi$ is satisfiable if and only if $\exists A'' \subseteq \mathbb{Z}$ such that $A''+A'' = X_{\phi}$.

        The running times of the above algorithms are all $\poly(n,m)$. Hence, we showed a polynomial-time reduction from 3-SAT to Sumset Recognition. 
    \end{proof}
